import{_ as o,a as n,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"List Bookings (Datagrid)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-bookings-list-gql","title":"List Bookings (Datagrid)","description":"Cursor-paginated bookings datagrid. Every booking column plus the linked order / order-item summary is populated on each row.","query":"query AdminBookings($first: Int, $after: String) {\\n  adminBookings(first: $first, after: $after) {\\n    edges {\\n      cursor\\n      node {\\n        id\\n        _id\\n        orderId\\n        orderIncrementId\\n        orderItemId\\n        productId\\n        productSku\\n        productName\\n        bookingType\\n        qty\\n        from\\n        to\\n        fromFormatted\\n        toFormatted\\n        bookingProductEventTicketId\\n        order\\n        orderItem\\n        createdAt\\n      }\\n    }\\n    pageInfo {\\n      hasNextPage\\n      endCursor\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminBookings\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/bookings/1\\",\\n            \\"_id\\": 1,\\n            \\"orderId\\": 8,\\n            \\"orderIncrementId\\": \\"00000000008\\",\\n            \\"orderItemId\\": 42,\\n            \\"productId\\": 99,\\n            \\"productSku\\": \\"BK-EVENT-01\\",\\n            \\"productName\\": \\"Concert Ticket\\",\\n            \\"bookingType\\": \\"event\\",\\n            \\"qty\\": 2,\\n            \\"from\\": 1716220800,\\n            \\"to\\": 1716224400,\\n            \\"fromFormatted\\": \\"20 May, 2026 12:00PM\\",\\n            \\"toFormatted\\": \\"20 May, 2026 13:00PM\\",\\n            \\"bookingProductEventTicketId\\": 5,\\n            \\"order\\": {\\n              \\"id\\": 8,\\n              \\"incrementId\\": \\"00000000008\\",\\n              \\"status\\": \\"processing\\",\\n              \\"customerName\\": \\"John Doe\\",\\n              \\"customerEmail\\": \\"john.doe@example.com\\",\\n              \\"grandTotal\\": 240,\\n              \\"orderCurrencyCode\\": \\"USD\\"\\n            },\\n            \\"orderItem\\": {\\n              \\"id\\": 42,\\n              \\"sku\\": \\"BK-EVENT-01\\",\\n              \\"name\\": \\"Concert Ticket\\",\\n              \\"qtyOrdered\\": 2\\n            },\\n            \\"createdAt\\": \\"2026-05-20 10:00:00\\"\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"hasNextPage\\": false,\\n        \\"endCursor\\": \\"MA==\\"\\n      },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/bookings/list.md","filePath":"api/graphql-api/admin/sales/bookings/list.md","lastUpdated":1787725411000}'),t={name:"api/graphql-api/admin/sales/bookings/list.md"};function i(d,e,s,c,l,m){return a(),n("div",null,e[0]||(e[0]=[r('<h1 id="list-bookings-datagrid" tabindex="-1">List Bookings (Datagrid) <a class="header-anchor" href="#list-bookings-datagrid" aria-label="Permalink to &quot;List Bookings (Datagrid)&quot;">​</a></h1><p>GraphQL counterpart of <code>GET /api/admin/bookings</code>. Returns a cursor-paginated list of bookings — the same rows shown on the admin <strong>Sales → Bookings</strong> datagrid. Every booking <strong>column</strong> plus the linked <code>order</code> and <code>orderItem</code> summaries are populated on each row, so the field set is identical to <a href="/api/graphql-api/admin/sales/bookings/detail.html">Booking Detail</a>.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><p><code>adminBookings(first, after, id, order_id, qty, product_id, from_from, from_to, to_from, to_to, created_at_from, created_at_to, sort, order)</code> — a cursor <code>QueryCollection</code>. Every REST query parameter is also exposed as a GraphQL argument; see the <a href="/api/rest-api/admin/sales/bookings/list.html">REST page</a> for the full argument table.</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.bookings.view</code></p><h3 id="order-objects-are-returned-whole" tabindex="-1">Order objects are returned whole <a class="header-anchor" href="#order-objects-are-returned-whole" aria-label="Permalink to &quot;Order objects are returned whole&quot;">​</a></h3><p><code>order</code> and <code>orderItem</code> are returned as JSON — <strong>query them bare, without a sub-selection</strong> (<code>order</code>, not <code>order { … }</code>). The whole object comes back. See <a href="/api/graphql-api/admin/sales/bookings/detail.html">Booking Detail</a> for the keys inside each.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>Every field is populated on each row (the booking columns, the booking sub-type, the two time-window representations, and the <code>order</code> / <code>orderItem</code> summary objects). The booking window is exposed two ways: <code>from</code> / <code>to</code> are raw <strong>unix timestamps</strong> (integers), and <code>fromFormatted</code> / <code>toFormatted</code> are the same instants pre-rendered as <code>d M, Y H:iA</code> strings (e.g. <code>&quot;20 May, 2026 12:00PM&quot;</code>). For non-time-based booking sub-types all four can be <code>null</code>. The full per-field reference is on the <a href="/api/graphql-api/admin/sales/bookings/detail.html">Booking Detail</a> page.</p><h2 id="listing-vs-fetching-one" tabindex="-1">Listing vs. fetching one <a class="header-anchor" href="#listing-vs-fetching-one" aria-label="Permalink to &quot;Listing vs. fetching one&quot;">​</a></h2><p>The listing already carries the full payload — fetching a single booking by id (<code>adminBooking(id:)</code>) is only needed when you already hold a booking id and want just that record. Typical flow: list with <code>adminBookings</code>, read <code>_id</code> from the row you want, then fetch the full record with <code>adminBooking(id:)</code>.</p>',12)]))}const p=o(t,[["render",i]]);export{g as __pageData,p as default};
